self.KB_CONTENT["card:757759"]={"id":"card:757759","ty":"card","sourceId":"757759","title":"『採購變更單建立作業』中的『匯率 (TE008)』為何？","ver":"iGP","topic":"變更單","keywords":["變更單","採購","幣別","匯率"],"y":"other","answer":"* 此欄位必須大於零。* 可點選(icon)或[F2]幣別匯率查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
