self.KB_CONTENT["card:784207"]={"id":"card:784207","ty":"card","sourceId":"784207","title":"『資產請購單憑證』中的『選擇請購單號 (AST.TI002)』為何？","ver":"GP4以上","topic":"憑證","keywords":["憑證","資產","購單","單號"],"y":"other","answer":"* 可輸入需列印之資產請購單號之起迄範圍。若空白表全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
