self.KB_CONTENT["card:779658"]={"id":"card:779658","ty":"card","sourceId":"779658","title":"『Wafer特性資料建立作業』的作業重點有哪些？","ver":"GP4以上","topic":"單身","keywords":["單身","進行","單頭","修正"],"y":"explain","answer":"■作業重點1.單頭與單身只可修改及查詢，不可新增及刪除。2.運用此建立作業進行Wafer的特性做修正，可防止使用者對於料號做不正當的修改。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
