self.KB_CONTENT["card:784544"]={"id":"card:784544","ty":"card","sourceId":"784544","title":"『資產請購資料更新作業』中的『輸入採購日期 (C8)』為何？","ver":"GP4以上","topic":"資產","keywords":["資產","採購","固定","年月"],"y":"other","answer":"* 指定欲產生之採購日期。* 當系統日≧固定資產現行年月時，預設系統日期。亦可修改，點選(icon)或[F2]日期快手查詢。* 所輸入之採購日期資料不可小於固定資產現行年月。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
