self.KB_CONTENT["card:784823"]={"id":"card:784823","ty":"card","sourceId":"784823","title":"『資產減損憑證』中的『選擇單別 (TC001)』為何？","ver":"GP4以上","topic":"憑證","keywords":["憑證","資產","單別"],"y":"other","answer":"* 單別代號資料。* 可點選(icon)或[F2]單別資料查詢，其單據性質需為「CD.減損」者之單別。輸入之單別資料必須存在於單據性質檔內。但不允許空白。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
