self.KB_CONTENT["field:754413"]={"id":"field:754413","ty":"field","sourceId":"754413","title":"付款逢__日","ver":"iGP","topic":"","keywords":[],"job":"付款條件建立作業","code":"NA011","answer":"* 可空白。非空白時，將來日期推算時若為不存在日期，則視為月底，所輸入之日期需介於 1~31 之間。* 例：付款加__個月 = 1 ，付款逢__日 = 3 1時，若付款日為 950305 則兌現日期為 950430。","file":"fields.jsonl"};
